changeSet.sql:
ALTER TABLE document.payments RENAME COLUMN document_id TO contract_id;
ALTER TABLE document.payments RENAME COLUMN amount TO total_amount;
ALTER TABLE document.payments RENAME COLUMN payment_date TO contract_payment_date;
ALTER TABLE document.payments RENAME COLUMN payment_completed_at TO paid_at;
ALTER TABLE document.payments RENAME COLUMN created_date TO created_at;
ALTER TABLE document.payments RENAME COLUMN last_modified_date TO updated_at;

ALTER TABLE document.payments ADD COLUMN IF NOT EXISTS buyer_in TEXT;
ALTER TABLE document.payments ADD COLUMN IF NOT EXISTS seller_in TEXT;
ALTER TABLE document.payments ADD COLUMN IF NOT EXISTS changed_payment_date TIMESTAMP;
ALTER TABLE document.payments ADD COLUMN IF NOT EXISTS contract_status TEXT;

UPDATE document.payments p
   SET buyer_in = c.buyer_in,
       seller_in = c.seller_in,
       contract_status = c.status
  FROM document.contracts c
 WHERE c.id = p.contract_id;

ALTER TABLE document.payments DROP COLUMN IF EXISTS buyer_id;
ALTER TABLE document.payments DROP COLUMN IF EXISTS seller_id;
ALTER TABLE document.payments DROP COLUMN IF EXISTS previous_payment_date;
